        let dtor_inst = c.core_instantiate(dtor_idx, std::iter::empty::<(&str, ModuleArg)>());
        let dtor_core = c.core_alias_export(dtor_inst, "t-dtor", ExportKind::Func);
        let res_ty = c.type_resource(ValType::I32, Some(dtor_core));
